-- Migration 0053_capture_inbox: generated by drizzle-kit (tables, keys, indexes), RLS and the column-list SET NULL actions hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #43)
-- The capture inbox (#43; PRD CA-1..CA-4, CA-9, CA-10):
--   * capture and workspace_capture_channel: tenant tables (tenantTable()) under FORCE RLS with
--     ws_isolation (tenantPolicy()). capture carries the unique (workspace_id, id) its composite FKs
--     target; every channel but manual and upload starts disabled (no row = disabled).
--   * The nullable composite FKs whose parent can go away (dedupe_of_capture_id, matter_hint_id and
--     document.source_capture_id) are ON DELETE SET NULL (<column>) (Postgres 15+), like 0038:
--     drizzle-kit writes a plain SET NULL, which would also null the NOT NULL workspace_id; its
--     snapshot keeps `set null`.
--   * document.source_capture_id gets its FK to capture (composite), left out by 0038 until the
--     table existed. The column is nullable and no row can name a capture yet, so it needs no cleanup.
--   * owner_definer_read lets app_capture_retention_targets() list the workspaces that have raw
--     objects past their ttl_at for the daily `system.capture.retention` job; it returns ids only.
-- Expand only: new tables, a policy, a function and one new constraint; no existing data is rewritten.
CREATE TABLE "capture" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"channel" text NOT NULL,
	"status" text DEFAULT 'received' NOT NULL,
	"raw_storage_key" text,
	"sha256" text,
	"mime" text NOT NULL,
	"size_bytes" bigint NOT NULL,
	"original_filename" text,
	"source_meta" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"dedupe_of_capture_id" uuid,
	"matter_hint_id" uuid,
	"ai_blocked" boolean DEFAULT false NOT NULL,
	"scan_status" text DEFAULT 'pending' NOT NULL,
	"pinned" boolean DEFAULT false NOT NULL,
	"ttl_at" timestamp with time zone,
	"created_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"processed_at" timestamp with time zone,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "capture_workspace_id_id_uq" UNIQUE("workspace_id","id"),
	CONSTRAINT "capture_channel_chk" CHECK (channel in ('share', 'upload', 'voice', 'camera', 'email', 'ics', 'whatsapp_export', 'bulk_import', 'manual')),
	CONSTRAINT "capture_status_chk" CHECK (status in ('received', 'scanning', 'queued', 'processing', 'needs_you', 'ready', 'applied', 'failed', 'duplicate', 'discarded', 'quarantined')),
	CONSTRAINT "capture_scan_status_chk" CHECK (scan_status in ('pending', 'clean', 'infected', 'skipped')),
	CONSTRAINT "capture_sha256_chk" CHECK (sha256 is null or sha256 ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "capture_size_chk" CHECK (size_bytes >= 0),
	CONSTRAINT "capture_not_duplicate_of_self_chk" CHECK (dedupe_of_capture_id is null or dedupe_of_capture_id <> id)
);
--> statement-breakpoint
CREATE TABLE "workspace_capture_channel" (
	"channel" text NOT NULL,
	"enabled" boolean DEFAULT false NOT NULL,
	"enabled_by" uuid,
	"enabled_at" timestamp with time zone,
	"disclosure_version" text,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "workspace_capture_channel_pkey" PRIMARY KEY("workspace_id","channel"),
	CONSTRAINT "workspace_capture_channel_channel_chk" CHECK (channel in ('share', 'upload', 'voice', 'camera', 'email', 'ics', 'whatsapp_export', 'bulk_import', 'manual')),
	CONSTRAINT "workspace_capture_channel_disclosure_chk" CHECK (not enabled or disclosure_version is not null)
);
