CREATE FUNCTION app_capture_retention_targets(p_now timestamptz)
  RETURNS TABLE (workspace_id uuid)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    SELECT DISTINCT c.workspace_id FROM capture c
    WHERE c.raw_storage_key IS NOT NULL AND c.ttl_at IS NOT NULL AND c.ttl_at <= p_now
      AND (NOT c.pinned OR c.status = 'discarded')
    ORDER BY c.workspace_id
    LIMIT 1000
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_capture_retention_targets(timestamptz) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_capture_retention_targets(timestamptz) TO causedeck_app;
